"""Hand-traced silhouettes. All points are percentages of the unrotated painting.
The order in each list is back to front. Children inherit their parent's rigid pose.
"""
def part(name, pivot, degrees, outline, parent=None):
    return dict(name=name, pivot=pivot, degrees=degrees, parent=parent,
                points=[tuple(map(float,p.split(','))) for p in outline.split()])

def head(pivot, outline, degrees=4):
    return part('head',pivot,degrees,outline)

def arm(pivot, outline, degrees):
    return part('hand',pivot,degrees,outline)

def prop(pivot, outline, degrees, parent=None):
    return part('prop',pivot,degrees,outline,parent)

def cloth(pivot, outline):
    return part('breath',pivot,1.4,outline)

